const { error } = require('console');
const fs = require('fs-extra');
const path = require('path');

var _robloxPathDict;
var _parseSystems;
var _options;

var luaEvents = []


function trimKey(key) {
    // remove file extension from key if have
    return key.replace(/\.[^.]+$/, '');
}



function genEvents(filePath) {
    var eventsFolder = path.dirname(path.dirname(filePath));

    var system = _parseSystems.GetSystemByFilePath(eventsFolder)

    // assert systemName not null
    if (!system) {
        throw new Error('未能根据事件路径获取对应的系统:' + eventsFolder);
    }

    const content = JSON.parse(fs.readFileSync(filePath, 'utf8'));

    eventsFolder = eventsFolder.replace(/\\/g, '/');

    for (const [key, value] of Object.entries(content)) {
        // deep clone value
        // 深度克隆 value
        let clonedValue = JSON.parse(JSON.stringify(value));

        // 创建新的事件对象
        let newEvent = {
            ...clonedValue,
            EventName: key,
            FolderPath: eventsFolder,
            SystemName: system.Name
        };

        // remove event from luaEvents if EventName and FolderPath equals
        luaEvents = luaEvents.filter(event => event.EventName !== newEvent.EventName || event.FolderPath !== newEvent.FolderPath);

        // 将新事件添加到 luaEvents 数组中
        luaEvents.push(newEvent);

    }
}




// 尝试生成路径, 如果有变更, 返回true
function tryGen(filePath) {

    var changed = false

    if (fs.existsSync(filePath)) {
        // if parent name is `.manifest`
        // 检查父文件夹是否为 .manifest
        const parentFolder = path.basename(path.dirname(filePath));
        if (parentFolder === '.manifest') {
            if ((filePath.endsWith('events.json'))) {
                genEvents(filePath);
                changed = true
            }
        }
    }

    return changed
}

function findAndGenSubfolders(basePath) {
    if (_options.isIgnoreFolder(path.resolve(basePath))) return
    var changed = false

    if (!fs.existsSync(basePath)) {
        // if parent exits ,try gen
        const parentPath = path.dirname(basePath);
        if (fs.existsSync(parentPath)) {
            return findAndGenSubfolders(parentPath);
        }
        return false
    }

    // is dir
    if (fs.lstatSync(basePath).isDirectory()) {

        for (const item of fs.readdirSync(basePath, { withFileTypes: true })) {

            const fullPath = path.join(basePath, item.name);
            changed |= findAndGenSubfolders(fullPath);
        }
    } else {
        changed |= tryGen(basePath)
    }
    return changed
}

module.exports = {
    Init: function (options) {
        _options = options
        _robloxPathDict = options.robloxPathDict;
        _parseSystems = options.parseSystems
    },

    TryGen: function (paths) {
        var changed = false
        for (const basePath of paths) {
            changed |= findAndGenSubfolders(basePath);
        }
        return changed
    },
    TryGenOnUpdate: function (events) {
        var changed = false

        for (var key in events) {
            basePath = path.dirname(key);
            if (fs.existsSync(basePath)) {
                changed |= findAndGenSubfolders(basePath)
            }
        }

        return changed
    },
    GetLuaEvents: function () {
        return luaEvents
    }

}